// Token vectors generated by edge-tts 7.3.1's generate_sec_ms_gec_v2(t) (the Python reference).
import test from 'node:test';
import assert from 'node:assert';
import { generateSecMsGec } from '../src/drm.js';

const VECTORS = {
  0: '52BC7A17B50DFEC9-28C4394775C8751CD2F6859C030C06DB1489ACAB3B3A7651831FC26895177ED6',
  1700000000: '2CD23A2CA0B2595A-F3C846C370E05F9CC83ACC5F995C5F5D87A4D0F14CE8936A0F902E64099E38A2',
  1792430000.5: 'AE196DFE9DEC3926-FCD1A840A383AD94250AE77035924101988D138B535CDC9B06BF22B2109AA5E6',
  1800000123: '99E54519B490BE5C-E162DB0977FBDCB9B86DD8148BF1BCDC3C0303176CE39852A42B415935C20654',
  2000000000: '2D62557F1142BC5D-FD9C30C68FF194A5EE6B45FEFC5E2BA1D1239F88A90569AB55CFFFAA7799F40E',
};

for (const [t, expected] of Object.entries(VECTORS)) {
  test(`Sec-MS-GEC matches edge-tts for t=${t}`, () => assert.strictEqual(generateSecMsGec(Number(t)), expected));
}

test('token is stable within a 5-minute window', () => {
  assert.strictEqual(generateSecMsGec(1800000000), generateSecMsGec(1800000000 + 299));
});
